struct ImageProcessor{width:u32,height:u32,pixels:Vec<u8>}
impl ImageProcessor{fn new(width:u32,height:u32)->Self{Self{width,height,pixels:vec![0;(width*height*4)as usize]}}
fn grayscale(&mut self){for chunk in self.pixels.chunks_exact_mut(4){let gray=(0.299*chunk[0]as f64+0.587*chunk[1]as f64+0.114*chunk[2]as f64)as u8;chunk[0]=gray;chunk[1]=gray;chunk[2]=gray;}}}
fn main(){let p=ImageProcessor::new(2,3);println!("{} {}",p.pixels.len(),p.pixels.iter().all(|&b|b==0));}

